// Personal gallery is independent of character portraits and per-floor state.
export function createUserPhotoLibrary(win){
 let database;const urls=new Map();const open=()=>database??=new Promise((resolve,reject)=>{const request=win.indexedDB.open('hypnoos-personal-photos',1);request.onupgradeneeded=()=>request.result.createObjectStore('photos',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});
 async function transaction(mode,operation){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction('photos',mode),request=operation(tx.objectStore('photos'));let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
 return{async list(){const rows=await transaction('readonly',store=>store.getAll());return rows.sort((a,b)=>b.createdAt-a.createdAt).map(row=>{if(!urls.has(row.id))urls.set(row.id,win.URL.createObjectURL(row.blob));return{id:row.id,albumId:'imported',name:row.name,label:'导入的照片',type:'imported',src:urls.get(row.id)};});},async importFiles(files){for(const file of files){if(!/^image\/(png|jpeg|webp|gif|avif|heic|heif)$/.test(file.type))throw Error('请选择图片文件');if(file.size>20*1024*1024)throw Error('单张照片不能超过 20 MB');await transaction('readwrite',store=>store.put({id:win.crypto.randomUUID(),name:file.name,blob:file,createdAt:Date.now()}));}},async remove(id){await transaction('readwrite',store=>store.delete(id));if(urls.has(id)){win.URL.revokeObjectURL(urls.get(id));urls.delete(id);}},destroy(){for(const url of urls.values())win.URL.revokeObjectURL(url);urls.clear();}};
}
